    Bug 1927629 - Fix browser_eventDialog.js when run after 2200 UTC. r=tobyp

    In most cases the string begins "Saturday, 19 October 2024, 01:00–", but if the event ends the next
    day, the format is "Saturday, 19 October 2024 at 23:00 –". Note the comma changes to " at".
    This test should pass in both cases.

    Differential Revision: https://phabricator.services.mozilla.com/D227123

diff --git a/calendar/test/browser/eventDialog/browser_eventDialog.js b/calendar/test/browser/eventDialog/browser_eventDialog.js
index 76a9f1a78f8..605a6383495 100644
--- a/calendar/test/browser/eventDialog/browser_eventDialog.js
+++ b/calendar/test/browser/eventDialog/browser_eventDialog.js
@@ -392,7 +392,10 @@ function checkTooltip(row, col, startTime, endTime) {
   currDate.addDuration(cal.createDuration(`P${7 * (row - 1) + (col - 1)}D`));
   const startDate = cal.dtz.formatter.formatDate(currDate);

-  Assert.stringContains(dateTime, `${startDate}, ${startTime.replace(/ [AP]M/, "")}`);
+  Assert.ok(dateTime.startsWith(startDate));
+
+  // AM/PM indicator (if there is one) removed if it's the same in endTime.
+  Assert.stringContains(dateTime, startTime.replace(/ [AP]M/, ""));

   // This could be on the next day if it is 00:00.
   Assert.ok(dateTime.endsWith(endTime));
